<script lang="ts">
  import{onDestroy}from'svelte';import{guessOs}from'#lib/api.ts';import{roadmapMediaApi,type ColorValue}from'#lib/roadmap-media-api.ts';import Notice from'#lib/ui/Notice.svelte';import CopyButton from'#lib/ui/CopyButton.svelte';
  let displays=$state<{id:number;name:string;width:number;height:number}[]>([]),display=$state(0),x=$state(0),y=$state(0),value=$state<ColorValue|null>(null),busy=$state(false),error=$state('');let requestId=0;const os=guessOs();
  async function load(){const id=++requestId;busy=true;error='';try{const next=await roadmapMediaApi.colorTargets();if(id===requestId){displays=next;display=next[0]?.id??0;}}catch(cause){if(id===requestId)error=String(cause);}finally{if(id===requestId)busy=false;}}
  async function sample(cursor=false){const id=++requestId;busy=true;error='';try{const next=await(cursor?roadmapMediaApi.colorCursor():roadmapMediaApi.colorSample(display,x,y));if(id===requestId)value=next;}catch(cause){if(id===requestId)error=String(cause);}finally{if(id===requestId)busy=false;}}
  onDestroy(()=>{requestId++;});
</script>
<div class="tool" aria-busy={busy}><Notice kind="info">Samples one screen pixel only when requested. On Windows, Pick under cursor hides Oxbox for three seconds so you can point to a color. Coordinate sampling uses physical image pixels, starting at the chosen display's top-left. No image is saved or uploaded.</Notice>
  {#if os==='windows'}<button class="btn btn-primary" onclick={()=>sample(true)} disabled={busy}>{busy?'Sampling…':'Pick under cursor in 3 seconds'}</button>{/if}
  <button class="btn" onclick={load} disabled={busy}>Load displays for coordinate sampling</button>
  {#if displays.length}<label class="field"><span class="field-label">Display</span><select class="input" bind:value={display} disabled={busy}>{#each displays as item}<option value={item.id}>{item.name} ({item.width} × {item.height})</option>{/each}</select></label><div class="row"><label class="field"><span class="field-label">X (pixels)</span><input class="input" type="number" min="0" bind:value={x} disabled={busy}/></label><label class="field"><span class="field-label">Y (pixels)</span><input class="input" type="number" min="0" bind:value={y} disabled={busy}/></label><button class="btn" onclick={()=>sample()} disabled={busy}>Sample coordinate</button></div>{/if}
  {#if value}<div class="card result"><div class="swatch" style:background={value.hex} aria-label="Sampled color {value.hex}"></div>{#each [['HEX',value.hex],['RGB',value.rgb.join(', ')],['HSL',`${value.hsl[0]}°, ${value.hsl[1]}%, ${value.hsl[2]}%`],['CMYK',value.cmyk.map(n=>`${n}%`).join(', ')]] as [label,text]}<div class="row"><strong>{label}</strong><output class="mono">{text}</output><CopyButton {text}/></div>{/each}</div>{/if}{#if error}<Notice kind="error">{error}</Notice>{/if}
</div><style>.tool{display:grid;gap:var(--s-4)}.row{display:flex;gap:var(--s-3);align-items:center;flex-wrap:wrap}.result{display:grid;gap:var(--s-3);padding:var(--s-4)}.swatch{width:var(--s-8);height:var(--s-8);border:1px solid var(--border-strong);border-radius:var(--r-sm)}.btn{justify-self:start}</style>
